//! Tests for the server code generated by the `rpc` macro.

use jsonrpsee::{core::RpcResult, proc_macros::rpc, RpcModule};

#[rpc(server, namespace = "test")]
trait Api {
    /// An async method with a required and an optional parameter.
    #[method(name = "add")]
    async fn add(&self, a: u64, b: Option<u64>) -> RpcResult<u64>;

    /// A sync method with only an optional parameter.
    #[method(name = "optional")]
    fn optional(&self, a: Option<u64>) -> RpcResult<Option<u64>>;

    /// A method without parameters.
    #[method(name = "noParams")]
    fn no_params(&self) -> RpcResult<u64>;

    /// A method that runs on the blocking pool.
    #[method(name = "blocking", blocking)]
    fn blocking(&self, a: u64) -> RpcResult<u64>;

    /// An async method with a default body.
    #[method(name = "default")]
    async fn default_body(&self, a: u64) -> RpcResult<u64> {
        Ok(a + self.no_params()?)
    }

    /// An async method with an argument borrowed from the params.
    #[method(name = "echo")]
    async fn echo(&self, s: &str) -> RpcResult<String>;
}

struct Api;

impl ApiServer for Api {
    async fn add(&self, a: u64, b: Option<u64>) -> RpcResult<u64> {
        Ok(a + b.unwrap_or_default())
    }

    fn optional(&self, a: Option<u64>) -> RpcResult<Option<u64>> {
        Ok(a)
    }

    fn no_params(&self) -> RpcResult<u64> {
        Ok(7)
    }

    fn blocking(&self, a: u64) -> RpcResult<u64> {
        Ok(a * 2)
    }

    async fn echo(&self, s: &str) -> RpcResult<String> {
        Ok(s.to_owned())
    }
}

/// Calls `method` and returns the raw response. `params` is the JSON of the `params` member, or
/// `None` to leave it out.
async fn call(module: &RpcModule<Api>, method: &str, params: Option<&str>) -> String {
    let params = params.map(|params| format!(r#","params":{params}"#)).unwrap_or_default();
    let request = format!(r#"{{"jsonrpc":"2.0","id":0,"method":"{method}"{params}}}"#);
    module.raw_json_request(&request, 1).await.unwrap().0
}

fn result(result: &str) -> String {
    format!(r#"{{"jsonrpc":"2.0","id":0,"result":{result}}}"#)
}

/// The invalid params error, where `data` is the JSON-escaped content of its `data` string.
fn invalid_params(data: &str) -> String {
    format!(
        r#"{{"jsonrpc":"2.0","id":0,"error":{{"code":-32602,"message":"Invalid params","data":"{data}"}}}}"#
    )
}

#[tokio::test]
async fn decodes_positional_params() {
    let module = Api.into_rpc();

    assert_eq!(call(&module, "test_add", Some("[1,2]")).await, result("3"));
    // Trailing optional parameters can be left out or null.
    assert_eq!(call(&module, "test_add", Some("[1]")).await, result("1"));
    assert_eq!(call(&module, "test_add", Some("[1,null]")).await, result("1"));

    assert_eq!(call(&module, "test_optional", Some("[5]")).await, result("5"));
    assert_eq!(call(&module, "test_optional", Some("[]")).await, result("null"));
    assert_eq!(call(&module, "test_optional", None).await, result("null"));

    assert_eq!(call(&module, "test_noParams", None).await, result("7"));
    assert_eq!(call(&module, "test_noParams", Some("[]")).await, result("7"));

    assert_eq!(call(&module, "test_echo", Some(r#"["hi"]"#)).await, result(r#""hi""#));
}

#[tokio::test]
async fn rejects_invalid_params() {
    let module = Api.into_rpc();

    // A required parameter is missing.
    let missing = invalid_params("No more params");
    assert_eq!(call(&module, "test_add", Some("[]")).await, missing);
    assert_eq!(call(&module, "test_add", None).await, missing);

    // A parameter has the wrong type.
    assert_eq!(
        call(&module, "test_add", Some(r#"["one"]"#)).await,
        invalid_params(r#"invalid type: string \"one\", expected u64 at line 1 column 5"#)
    );

    // Parameters are positional, so objects are rejected even if every parameter is optional.
    assert_eq!(
        call(&module, "test_add", Some(r#"{"a":1,"b":2}"#)).await,
        invalid_params(
            r#"Invalid params. Expected one of '[', ']' or ',' but found \"{\\\"a\\\":1,\\\"b\\\":2}\""#
        )
    );
    assert_eq!(
        call(&module, "test_optional", Some("{}")).await,
        invalid_params(r#"Invalid params. Expected one of '[', ']' or ',' but found \"{}\""#)
    );
}

#[tokio::test]
async fn runs_blocking_and_default_methods() {
    let module = Api.into_rpc();

    assert_eq!(call(&module, "test_blocking", Some("[2]")).await, result("4"));
    assert_eq!(call(&module, "test_default", Some("[1]")).await, result("8"));
}
